python -c "
from collections.abc import Mapping
import toolz

class CustomMapping(Mapping):
    def __init__(self, data):
        self._data = data

    def __getitem__(self, key):
        return self._data[key]

    def __iter__(self):
        return iter(self._data)

    def __len__(self):
        return len(self._data)

# Test merge with custom mapping
cm1 = CustomMapping({'a': 1, 'b': 2})
cm2 = {'b': 3, 'c': 4}

result = toolz.merge(cm1, cm2)
print('merge result:', result)

# Test merge_with with custom mapping
def sum_func(values):
    return sum(values)

result2 = toolz.merge_with(sum_func, cm1, cm2)
print('merge_with result:', result2)
"
